#!/usr/bin/env node
/**
 * Validate the JSON configuration and generate the typed registry from it.
 *
 *   node scripts/config.mjs validate   check config/ against the schema and cross-file rules
 *   node scripts/config.mjs generate   validate, then write the generated files
 *   node scripts/config.mjs check      fail if the generated files are not what generate would write
 *
 * Generated: src/generated/config-registry.ts (what the app imports),
 *            config/schema.json and config/release.schema.json (editor IntelliSense).
 */
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { format, resolveConfig } from 'prettier';
import { z } from 'zod';
import { countrySchema, releaseSchema, validateConfig } from '../config/schema.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const configDir = join(root, 'config');
const outputs = {
  registry: join(root, 'src/generated/config-registry.ts'),
  countrySchema: join(configDir, 'schema.json'),
  releaseSchema: join(configDir, 'release.schema.json'),
};

function readJson(path) {
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch (error) {
    throw new Error(`${path}: ${error.message}`);
  }
}

function loadSources() {
  const releasePath = join(configDir, 'release.json');
  if (!existsSync(releasePath)) throw new Error('config/release.json is missing');
  const countriesDir = join(configDir, 'countries');
  const files = existsSync(countriesDir)
    ? readdirSync(countriesDir).filter(name => name.endsWith('.json')).sort()
    : [];
  return {
    release: readJson(releasePath),
    countries: files.map(file => ({ file, value: readJson(join(countriesDir, file)) })),
  };
}

/** Key-sorted JSON, so the hash does not depend on field order or formatting. */
function canonical(value) {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value)
      .sort()
      .map(key => `${JSON.stringify(key)}:${canonical(value[key])}`)
      .join(',')}}`;
  }
  return JSON.stringify(value);
}

const withoutSchemaKey = ({ $schema, ...rest }) => rest;

async function pretty(code, parser, filepath) {
  const options = (await resolveConfig(filepath)) ?? {};
  return format(code, { ...options, parser });
}

async function build(validated) {
  const release = withoutSchemaKey(validated.release);
  const countries = validated.countries.map(withoutSchemaKey);
  const contentSha256 = createHash('sha256').update(canonical({ release, countries })).digest('hex');

  const registry = `/* eslint-disable */
// GENERATED by scripts/config.mjs from config/. Do not edit by hand.
// Regenerate with \`npm run config:generate\`; \`npm run config:check\` fails if this is stale.

export const CONFIG_RELEASE = {
  configVersion: ${JSON.stringify(release.configVersion)},
  schemaVersion: ${release.schemaVersion},
  contentSha256: ${JSON.stringify(contentSha256)},
} as const;

export const DEFAULT_COUNTRY_CODE = ${JSON.stringify(release.defaultCountry)} as const;

export const COUNTRY_DEFINITIONS = ${JSON.stringify(countries, null, 2)} as const;
`;
  const schemaJson = schema => JSON.stringify(z.toJSONSchema(schema, { target: 'draft-7' }), null, 2) + '\n';
  return {
    [outputs.registry]: await pretty(registry, 'typescript', outputs.registry),
    [outputs.countrySchema]: await pretty(schemaJson(countrySchema), 'json', outputs.countrySchema),
    [outputs.releaseSchema]: await pretty(schemaJson(releaseSchema), 'json', outputs.releaseSchema),
  };
}

async function main(command) {
  if (!['validate', 'generate', 'check'].includes(command)) {
    console.error('usage: node scripts/config.mjs <validate|generate|check>');
    process.exit(2);
  }
  const validated = validateConfig(loadSources());
  if (!validated.ok) {
    console.error(`config is invalid (${validated.errors.length} problem${validated.errors.length === 1 ? '' : 's'}):`);
    for (const error of validated.errors) console.error(`  - ${error}`);
    process.exit(1);
  }
  if (command === 'validate') {
    console.log(`config valid: ${validated.countries.length} countries (${validated.countries.map(c => c.code).join(', ')})`);
    return;
  }
  const expected = await build(validated);
  if (command === 'generate') {
    for (const [path, content] of Object.entries(expected)) {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
      console.log(`wrote ${path.replace(`${root}/`, '')}`);
    }
    return;
  }
  const stale = Object.entries(expected).filter(
    ([path, content]) => !existsSync(path) || readFileSync(path, 'utf8') !== content
  );
  if (stale.length > 0) {
    console.error('generated config is out of date; run `npm run config:generate` and commit:');
    for (const [path] of stale) console.error(`  - ${path.replace(`${root}/`, '')}`);
    process.exit(1);
  }
  console.log('generated config is current');
}

main(process.argv[2]).catch(error => {
  console.error(error.message);
  process.exit(1);
});
